<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'; import RemoteSelect from '../product/RemoteSelect.vue'; import StatusTag from './StatusTag.vue';
type Item=Record<string,unknown>; const props=defineProps<{entityId:string;loadItems:(id:string)=>Promise<Item[]>;createItem:(id:string,body:Item)=>Promise<unknown>;retryItem:(id:string)=>Promise<unknown>;loadPeople:()=>Promise<Item[]>}>(); const emit=defineEmits<{open:[item:Item]}>();
const items=ref<Item[]>([]),people=ref<Array<{value:string;label:string}>>([]),type=ref('dev'),statusFilter=ref(''),assignee=ref(''),note=ref(''),loading=ref(false),saving=ref(false),retrying=ref(''),success=ref(''),error=ref(''); const visibleItems=()=>statusFilter.value?items.value.filter(item=>String(item.syncStatus||item.status||'')===statusFilter.value):items.value; const load=async()=>{loading.value=true;try{items.value=await props.loadItems(props.entityId)}catch(e){error.value=e instanceof Error?e.message:'关联工单加载失败'}finally{loading.value=false}};watch(()=>props.entityId,load,{immediate:true});onMounted(async()=>{try{people.value=(await props.loadPeople()).map(x=>({value:String(x.name||x.id||''),label:String(x.name||x.id||'')})).filter(x=>x.value)}catch(e){error.value='负责人加载失败'}});const create=async()=>{if(!assignee.value){error.value='请选择负责人';return} saving.value=true;try{await props.createItem(props.entityId,{taskType:type.value,assigneeName:assignee.value,note:note.value});assignee.value='';note.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'创建工作项失败'}finally{saving.value=false}};const retry=async(id:string)=>{retrying.value=id;error.value='';success.value='';try{await props.retryItem(id);success.value='同步重试已提交';await load()}catch(e){error.value=e instanceof Error?e.message:'重试失败'}finally{retrying.value=''}};
</script>
<template><div class="work-items"><h4>关联工作项</h4><p v-if="loading" class="state">正在加载关联工单…</p><p v-else-if="error" class="state error">{{error}}</p><p v-else-if="success" class="form-feedback">{{success}}</p><ul v-else-if="visibleItems().length"><li v-for="(item,index) in visibleItems()" :key="String(item.id||index)"><strong>{{item.taskType||item.type||'任务'}}</strong><button class="link-button" @click="emit('open',item)">{{item.title||'未命名工作项'}}</button><StatusTag :status="String(item.syncStatus||item.status||'')"/><small v-if="item.assigneeName">负责人：{{item.assigneeName}}</small><small v-if="item.retryCount">已重试 {{item.retryCount}} 次</small><p v-if="item.syncStatus==='FAILED' && item.lastError" class="form-feedback error">失败原因：{{item.lastError}}</p><small v-if="item.nextRetryAt">下次重试：{{item.nextRetryAt}}</small><button v-if="item.syncStatus==='FAILED'" class="secondary"  :disabled="retrying===String(item.id)" @click="retry(String(item.id))">{{retrying===String(item.id)?'重试中…':'重试'}}</button></li></ul><p v-else class="muted">暂无匹配工作项</p><div class="form-grid"><select v-model="statusFilter"><option value="">全部同步状态</option><option value="PENDING">待同步</option><option value="SUCCESS">已同步</option><option value="FAILED">同步失败</option></select><select v-model="type"><option value="dev">研发任务</option><option value="design">设计任务</option><option value="bug">缺陷</option></select><RemoteSelect v-model="assignee" label="负责人" :options="people" placeholder="请选择负责人"/></div><textarea v-model="note" rows="2" placeholder="备注"/><button class="primary" :disabled="saving" @click="create">{{saving?'创建中…':'创建下游工作项'}}</button></div></template>
